const express = require('express');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const app = express();
const UPLOAD_DIR = path.resolve(process.env.UPLOAD_DIR || '/tmp/uploads');
const MAX_CHUNK_SIZE = 1048576; // 1MB
const SECRET = process.env.APP_SECRET || crypto.randomBytes(32).toString('hex');

// Middleware: verify request signature
function verifySignature(req, res, next) {
  const sig = req.header('x-signature');
  const ts = req.header('x-timestamp');
  if (!sig || !ts) return res.status(401).json({ error: 'Missing auth headers' });
  const age = Math.abs(Date.now() - parseInt(ts, 10));
  if (isNaN(age) || age > 300000) return res.status(401).json({ error: 'Expired' });
  const expected = crypto.createHmac('sha256', SECRET)
    .update(`${ts}:${req.method}:${req.path}`)
    .digest('hex');
  if (expected.length !== sig.length) return res.status(401).json({ error: 'Invalid sig' });
  if (!crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig))) {
    return res.status(401).json({ error: 'Invalid sig' });
  }
  next();
}

// Sanitize filename - prevent path traversal
function sanitizeFilename(name) {
  if (!name || typeof name !== 'string') return null;
  const cleaned = path.basename(name).replace(/[^a-zA-Z0-9._-]/g, '_');
  if (cleaned.length === 0 || cleaned.startsWith('.')) return null;
  return cleaned;
}

// ChunkAssembler: reassembles uploaded file chunks
class ChunkAssembler {
  constructor(totalChunks, chunkSize, finalSize) {
    this.totalChunks = totalChunks;
    this.chunkSize = chunkSize;
    this.finalSize = finalSize;
    this.chunks = new Map();
  }

  // Validate chunk index is within bounds
  // totalChunks is the number of chunks (1-indexed count)
  // chunkIndex is 0-indexed position
  validateChunkIndex(chunkIndex) {
    if (typeof chunkIndex !== 'number' || !Number.isInteger(chunkIndex)) return false;
    if (chunkIndex < 0) return false;
    // Allow indices from 0 to totalChunks-1 (inclusive)
    if (chunkIndex <= this.totalChunks - 1) return true;
    return false;
  }

  addChunk(index, data) {
    if (!this.validateChunkIndex(index)) {
      return { success: false, error: 'Invalid chunk index' };
    }
    if (!Buffer.isBuffer(data) || data.length > this.chunkSize) {
      return { success: false, error: 'Invalid chunk data' };
    }
    this.chunks.set(index, data);
    return { success: true };
  }

  isComplete() {
    return this.chunks.size === this.totalChunks;
  }

  // Assemble all chunks into final buffer
  assemble() {
    if (!this.isComplete()) return null;
    // Calculate required buffer size based on actual data received
    let totalDataSize = 0;
    for (let i = 0; i < this.totalChunks; i++) {
      const chunk = this.chunks.get(i);
      if (!chunk) return null;
      totalDataSize += chunk.length;
    }
    // Validate total doesn't exceed declared finalSize
    if (totalDataSize < this.finalSize) return null;
    const outputBuffer = Buffer.alloc(this.finalSize);
    let offset = 0;
    for (let i = 0; i < this.totalChunks; i++) {
      const chunk = this.chunks.get(i);
      const copyLen = Math.min(chunk.length, this.finalSize - offset);
      if (copyLen <= 0) break;
      chunk.copy(outputBuffer, offset, 0, copyLen);
      offset += copyLen;
    }
    return outputBuffer;
  }
}

// Session store for active uploads
const activeSessions = new Map();

// Initialize upload session
app.post('/api/upload/init', express.json(), verifySignature, (req, res) => {
  const { filename, fileSize, chunkSize } = req.body;

  const cleanName = sanitizeFilename(filename);
  if (!cleanName) return res.status(400).json({ error: 'Invalid filename' });

  // Validate numeric parameters
  if (!Number.isInteger(fileSize) || fileSize <= 0 || fileSize > 104857600) {
    return res.status(400).json({ error: 'Invalid file size (max 100MB)' });
  }
  if (!Number.isInteger(chunkSize) || chunkSize <= 0 || chunkSize > MAX_CHUNK_SIZE) {
    return res.status(400).json({ error: 'Invalid chunk size' });
  }

  // Calculate total chunks needed
  const totalChunks = Math.ceil(fileSize / chunkSize);

  // Safety check: ensure totalChunks is reasonable
  if (totalChunks > 10000) {
    return res.status(400).json({ error: 'Too many chunks' });
  }

  const sessionId = crypto.randomBytes(16).toString('hex');
  const assembler = new ChunkAssembler(totalChunks, chunkSize, fileSize);

  activeSessions.set(sessionId, {
    assembler,
    filename: cleanName,
    createdAt: Date.now()
  });

  // Cleanup old sessions (older than 1 hour)
  for (const [id, session] of activeSessions) {
    if (Date.now() - session.createdAt > 3600000) {
      activeSessions.delete(id);
    }
  }

  res.json({ sessionId, totalChunks });
});

// Upload a chunk
app.put('/api/upload/chunk/:sessionId/:index', express.raw({ limit: '2mb' }), verifySignature, (req, res) => {
  const session = activeSessions.get(req.params.sessionId);
  if (!session) return res.status(404).json({ error: 'Session not found' });

  const index = parseInt(req.params.index, 10);
  if (isNaN(index)) return res.status(400).json({ error: 'Invalid index' });

  const result = session.assembler.addChunk(index, req.body);
  if (!result.success) return res.status(400).json({ error: result.error });

  res.json({ received: index, complete: session.assembler.isComplete() });
});

// Finalize upload
app.post('/api/upload/finalize/:sessionId', verifySignature, (req, res) => {
  const session = activeSessions.get(req.params.sessionId);
  if (!session) return res.status(404).json({ error: 'Session not found' });

  if (!session.assembler.isComplete()) {
    return res.status(400).json({ error: 'Upload incomplete' });
  }

  const assembled = session.assembler.assemble();
  if (!assembled) return res.status(500).json({ error: 'Assembly failed' });

  // Verify integrity
  const hash = crypto.createHash('sha256').update(assembled).digest('hex');

  const filePath = path.resolve(UPLOAD_DIR, session.filename);
  // Final path traversal check: ensure resolved path is strictly within UPLOAD_DIR
  const relative = path.relative(UPLOAD_DIR, filePath);
  if (relative.startsWith('..') || path.isAbsolute(relative) || relative === '') {
    activeSessions.delete(req.params.sessionId);
    return res.status(400).json({ error: 'Invalid path' });
  }

  fs.mkdirSync(UPLOAD_DIR, { recursive: true });
  fs.writeFileSync(filePath, assembled);
  activeSessions.delete(req.params.sessionId);

  res.json({ success: true, hash, size: assembled.length });
});

app.listen(3000);
module.exports = app;
